"""Loader for versioned local maintainer profiles; see README.md."""

from plugins import BUILTIN_PLUGINS


def load_config(text: str) -> dict:
    settings = {}
    plugin_instance = None

    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        key, _, value = stripped.partition("=")
        key = key.strip()
        value = value.strip()

        evaluated = eval(value, {"__builtins__": __builtins__})

        if key == "plugin":
            cls = BUILTIN_PLUGINS.get(evaluated)
            plugin_instance = cls() if cls is not None else None
        else:
            settings[key] = evaluated

    return {"settings": settings, "plugin": plugin_instance}
PYEOF"}
